export class HandleRegistrationComponent {
  public readonly registrationId = input.required<string>();
  protected readonly addonActionError = signal<undefined | unknown>(undefined);
  protected readonly addonActionMessage = signal('');
  private readonly rpc = AppRpc.injectClient();
  protected readonly cancelAddonMutation = injectMutation(() =>
    this.rpc.events.cancelRegistrationAddon.mutationOptions(),
  );
  protected readonly redeemAddonMutation = injectMutation(() =>
    this.rpc.events.redeemRegistrationAddon.mutationOptions(),
  );
  protected readonly undoAddonMutation = injectMutation(() =>
    this.rpc.events.undoRegistrationAddonRedemption.mutationOptions(),
  );
  protected readonly addonMutationPending = computed(
    () =>
      this.cancelAddonMutation.isPending() ||
      this.redeemAddonMutation.isPending() ||
      this.undoAddonMutation.isPending(),
  );
  // TanStack's default networkMode ('online') pauses the mutation while the
  // browser is offline and continues it when the connection returns.
  protected readonly checkInMutation = injectMutation(() => ({
    ...this.rpc.events.checkInRegistration.mutationOptions(),
    retry: rpcTransportRetry,
    retryDelay: rpcTransportRetryDelay,
  }));
  protected readonly checkInState = computed(() =>
    scanCheckInState({
      error: this.checkInMutation.error(),
      failureCount: this.checkInMutation.failureCount(),
      isError: this.checkInMutation.isError(),
      isPaused: this.checkInMutation.isPaused(),
      isPending: this.checkInMutation.isPending(),
      isSuccess: this.checkInMutation.isSuccess(),
    }),
  );
  /**
   * An unconfirmed check-in that the server answered with an internal error
   * instead of a dropped connection. Internal wording stays hidden, as with
   * every scanner error.
   */
  protected readonly checkInServerUnconfirmed = computed(
    () =>
      this.checkInState() === 'notConfirmed' &&
      hasErrorTag(
        this.checkInMutation.error(),
        'EventRegistrationInternalError',
      ),
  );
  protected readonly scanTicketQuery = injectQuery(() => ({
    ...this.rpc.events.scanTicket.queryOptions({
      registrationId: this.registrationId(),
    }),
    retry: rpcTransportRetry,
    retryDelay: rpcTransportRetryDelay,
  }));
  protected readonly guestCheckInCount = signal(0);
  protected readonly selectedGuestCheckInCount = computed(() => {
    const scanResult = this.scanTicketQuery.data()?.registration;
    if (!scanResult) {
      return 0;
    }
    return Math.min(this.guestCheckInCount(), scanResult.remainingGuestCount);
  });
  protected readonly selectedSpotCheckInCount = computed(() => {
    const scanResult = this.scanTicketQuery.data()?.registration;
    if (!scanResult) {
      return 0;
    }
    return (
      (scanResult.attendeeCheckedIn ? 0 : 1) + this.selectedGuestCheckInCount()
    );
  });
  private readonly localCheckInCompleted = signal(false);
  protected readonly checkInCompleted = computed(
    () =>
      this.localCheckInCompleted() ||
      (this.checkInMutation.isSuccess() &&
        this.selectedSpotCheckInCount() === 0),
  );
  protected readonly faArrowLeft = faArrowLeft;
  protected readonly pendingAddonId = signal<string | undefined>(undefined);
  protected readonly registrationAddonCancellationBlockedMessage =
    registrationAddonCancellationBlockedMessage;
  protected readonly registrationAddonQuantitySummary =
    registrationAddonQuantitySummary;
  protected readonly registrationAddonRefundStatusLabel =
    registrationAddonRefundStatusLabel;
  protected readonly scanCheckInActionDisabled = scanCheckInActionDisabled;
  protected readonly scanCheckInButtonLabel = scanCheckInButtonLabel;
  protected readonly guestInputLocked = computed(() =>
    scanGuestInputLocked(this.checkInState()),
  );
  protected readonly scanCheckInTimingIssueCopy = scanCheckInTimingIssueCopy;
  protected readonly scanRegistrationStatusIssueCopy =
    scanRegistrationStatusIssueCopy;
  protected readonly scanSpotCountLabel = scanSpotCountLabel;
  private readonly dialog = inject(MatDialog);
  private readonly queryClient = inject(QueryClient);
  private readonly redeemIntentStore = new RegistrationAddonRedeemIntentStore();

  checkIn() {
    const state = this.checkInState();
    const resendPayload = scanCheckInRetryPayload(
      state,
      this.checkInMutation.variables(),
    );
    if (resendPayload) {
      // Resend the original request unchanged. The ticket may already show the
      // committed count after a reconnect refetch.
      if (!this.checkInMutation.isPending()) {
        this.sendCheckIn(resendPayload);
      }
      return;
    }

    const scanResult = this.scanTicketQuery.data()?.registration;
    if (
      !scanResult ||
      scanCheckInActionDisabled({
        allowCheckin: scanResult.allowCheckin,
        completed: this.checkInCompleted(),
        mutationPending: this.checkInMutation.isPending(),
        spotCount: this.selectedSpotCheckInCount(),
      })
    )
      return;

    // The expected count stays the one the helper saw.
    this.sendCheckIn(
      scanCheckInPayload({
        expectedAttendeeCheckedIn: scanResult.attendeeCheckedIn,
        expectedCheckedInGuestCount: scanResult.checkedInGuestCount,
        guestCheckInCount: this.selectedGuestCheckInCount(),
        registrationId: this.registrationId(),
      }),
    );
  }

  updateGuestCheckInCount(event: Event) {
    const input = event.target;
    if (!(input instanceof HTMLInputElement)) {
      return;
    }
    const remainingGuestCount =
      this.scanTicketQuery.data()?.registration.remainingGuestCount ?? 0;
    this.guestCheckInCount.set(
      scanGuestCheckInCountFromInput({
        inputValue: input.value,
        remainingGuestCount,
      }),
    );

    });
  }).pipe(Effect.catch(mapRegistrationScanInternalError)),
'events.checkInRegistration': (
  {
    expectedAttendeeCheckedIn,
    expectedCheckedInGuestCount,
    guestCheckInCount,
    operationKey,
    registrationId,
  },
  _options,
) =>
  Effect.gen(function* () {
    yield* RpcAccess.ensureAuthenticated();
    const { tenant } = yield* RpcAccess.current();
    const user = yield* RpcAccess.requireUser();
    if (!Number.isInteger(guestCheckInCount) || guestCheckInCount < 0) {
      return yield* Effect.fail(
        new EventRegistrationConflictError({
          message: 'Enter a whole number of guests, starting at zero.',
        }),
      );
    }
    if (
      !Number.isInteger(expectedCheckedInGuestCount) ||
      expectedCheckedInGuestCount < 0
    ) {
      return yield* Effect.fail(
        new EventRegistrationConflictError({
          message: 'Reload the ticket and try again.',
        }),
      );
    }

    const registration = yield* databaseEffect((database) =>
      database.query.eventRegistrations.findFirst({
        columns: {
          checkedInGuestCount: true,
          checkInTime: true,
          eventId: true,
          guestCount: true,
          id: true,
          registrationOptionId: true,
          status: true,
          userId: true,
        },
        where: {
          id: registrationId,
          tenantId: tenant.id,
        },
      }),
    );

    if (!registration) {
      return yield* Effect.fail(
        new EventRegistrationNotFoundError({
          message:
            'This ticket is no longer available. No change was made. Reopen the event and review its current sign-ups.',
        }),
      );
    }

    yield* ensureCanScanEventRegistration({
      eventId: registration.eventId,
      tenantId: tenant.id,
      user,
    });

    if (registration.userId === user.id) {
      return yield* Effect.fail(
        new EventRegistrationConflictError({
          message: 'Ask another organizer to check in this ticket.',
        }),
      );
    }

    const checkedInRegistration = yield* Database.use((database) =>
      database.transaction((tx) =>
        Effect.gen(function* () {
          const lockedRegistrations = yield* tx
            .select({
              checkedInGuestCount: eventRegistrations.checkedInGuestCount,
              checkInTime: eventRegistrations.checkInTime,
              eventId: eventRegistrations.eventId,
              guestCount: eventRegistrations.guestCount,
              id: eventRegistrations.id,
              registrationOptionId: eventRegistrations.registrationOptionId,
              status: eventRegistrations.status,
              userId: eventRegistrations.userId,
            })
            .from(eventRegistrations)
            .where(
              and(
                eq(eventRegistrations.id, registration.id),
                eq(eventRegistrations.tenantId, tenant.id),
              ),
            )
            .for('update');
          const lockedRegistration = lockedRegistrations[0];
          if (!lockedRegistration) {
            return yield* Effect.fail(
              new EventRegistrationNotFoundError({
                message:
                  'This ticket is no longer available. No change was made. Reopen the event and review its current sign-ups.',
              }),
            );
          }
          if (lockedRegistration.userId === user.id) {
            return yield* Effect.fail(
              new EventRegistrationConflictError({
                message: 'Ask another organizer to check in this ticket.',
              }),
            );
          }
          // A recorded operation is replayed before any state check: the
          // retry must succeed after the window closed or after another
          // operation changed the counts.
          const recordedCheckIns = yield* tx
            .select({
              actorUserId: eventRegistrationCheckIns.actorUserId,
              attendeeCheckedIn: eventRegistrationCheckIns.attendeeCheckedIn,
              checkInTime: eventRegistrationCheckIns.checkInTime,
              expectedAttendeeCheckedIn:
                eventRegistrationCheckIns.expectedAttendeeCheckedIn,
              expectedCheckedInGuestCount:
                eventRegistrationCheckIns.expectedCheckedInGuestCount,
              guestCheckInCount: eventRegistrationCheckIns.guestCheckInCount,
            })
            .from(eventRegistrationCheckIns)
            .where(
              and(
                eq(eventRegistrationCheckIns.registrationId, registration.id),
                eq(eventRegistrationCheckIns.operationKey, operationKey),
                eq(eventRegistrationCheckIns.tenantId, tenant.id),
              ),
            );
          const recordedCheckIn = recordedCheckIns[0];
          if (recordedCheckIn) {
            if (
              recordedCheckIn.guestCheckInCount !== guestCheckInCount ||
              recordedCheckIn.expectedCheckedInGuestCount !==
                expectedCheckedInGuestCount ||
              recordedCheckIn.expectedAttendeeCheckedIn !==
                expectedAttendeeCheckedIn ||
              recordedCheckIn.actorUserId !== user.id
            ) {
              return yield* Effect.fail(
                new EventRegistrationConflictError({
                  message:
                    'This check-in request does not match the one already recorded. Reload the ticket and confirm again.',
                }),
              );
            }
            return {
              _tag: 'CheckedIn' as const,
              alreadyCheckedIn:
                !recordedCheckIn.attendeeCheckedIn &&
                recordedCheckIn.guestCheckInCount === 0,
              checkInTime: recordedCheckIn.checkInTime,
            };
          }

          if (lockedRegistration.status !== 'CONFIRMED') {
            return yield* Effect.fail(
              new EventRegistrationConflictError({
                message: 'This ticket is not ready for check-in.',
              }),
            );
          }
          yield* ensureRegistrationMutationHasNoActiveTransfer(tx, {
            registrationId: lockedRegistration.id,
            tenantId: tenant.id,
          }).pipe(Effect.catch(mapRegistrationTransferGuardError));

          const lockedEvents = yield* tx
            .select({
              end: eventInstances.end,
              start: eventInstances.start,
            })
            .from(eventInstances)
            .where(
              and(
                eq(eventInstances.id, lockedRegistration.eventId),
                eq(eventInstances.tenantId, tenant.id),
              ),
            )
            .for('share');
          const lockedEvent = lockedEvents[0];
          if (!lockedEvent) {
            yield* Effect.logError(
              'Registration event was missing during check-in',
            ).pipe(
              Effect.annotateLogs({
                eventId: lockedRegistration.eventId,
                registrationId: lockedRegistration.id,
                tenantId: tenant.id,
              }),
            );
            return yield* Effect.fail(
              new EventRegistrationInternalError({
                message:
                  'The event details are unavailable, so no check-in was recorded. Contact an Evorto administrator.',
              }),
            );
          }

          if (
            lockedRegistration.checkedInGuestCount < 0 ||
            lockedRegistration.guestCount < 0 ||
            lockedRegistration.checkedInGuestCount >
              lockedRegistration.guestCount
          ) {
            yield* Effect.logError(
              'Registration guest counts were invalid during check-in',
            ).pipe(
              Effect.annotateLogs({
                checkedInGuestCount: lockedRegistration.checkedInGuestCount,
                guestCount: lockedRegistration.guestCount,
                registrationId: lockedRegistration.id,
                tenantId: tenant.id,
              }),
            );
            return yield* Effect.fail(
              new EventRegistrationInternalError({
                message:
                  'The guest details need Evorto administrator review, so no check-in was recorded.',
              }),
            );
          }
          if (
            lockedRegistration.checkedInGuestCount !==
            expectedCheckedInGuestCount
          ) {
            return yield* Effect.fail(
              new EventRegistrationConflictError({
                message:
                  'This ticket changed on another device. Review the current check-in count, then confirm again.',
              }),
            );
          }
          const lockedAttendeeCheckedIn =
            lockedRegistration.checkInTime !== null;
          if (
            (lockedAttendeeCheckedIn !== expectedAttendeeCheckedIn &&
              guestCheckInCount > 0) ||
            (!lockedAttendeeCheckedIn && expectedAttendeeCheckedIn)
          ) {
            return yield* Effect.fail(
              new EventRegistrationConflictError({
                message:
                  'This ticket changed on another device. Review the current check-in count, then confirm again.',
              }),
            );
          }
          const lockedRemainingGuestCount =
            lockedRegistration.guestCount -
            lockedRegistration.checkedInGuestCount;
          if (guestCheckInCount > lockedRemainingGuestCount) {
            return yield* Effect.fail(
              new EventRegistrationConflictError({
                message: guestCheckInLimitMessage(lockedRemainingGuestCount),
              }),
            );
          }
          const now = yield* registrationHandlerNow;
          const timingIssue = eventCheckInTimingIssue({
            end: lockedEvent.end,
            now,
            start: lockedEvent.start,
          });
          if (timingIssue) {
            return {
              _tag: 'TimingIssue' as const,
              reason: timingIssue,
            };
          }
          if (lockedRegistration.checkInTime && guestCheckInCount === 0) {
            // Stored so a lost response can be replayed after the window.
            yield* tx.insert(eventRegistrationCheckIns).values({
              actorUserId: user.id,
              attendeeCheckedIn: false,
              checkInTime: lockedRegistration.checkInTime,
              expectedAttendeeCheckedIn,
              expectedCheckedInGuestCount,
              guestCheckInCount: 0,
              operationKey,
              registrationId: lockedRegistration.id,
              tenantId: tenant.id,
            });
            return {
              _tag: 'CheckedIn' as const,
              alreadyCheckedIn: true,
              checkInTime: lockedRegistration.checkInTime,
            };
          }
          const checkedInSpotCount =
            (lockedRegistration.checkInTime ? 0 : 1) + guestCheckInCount;

          const updatedRegistrations = yield* tx
            .update(eventRegistrations)
            .set({
              ...(!lockedRegistration.checkInTime && { checkInTime: now }),
              checkedInGuestCount: sql`${eventRegistrations.checkedInGuestCount} + ${guestCheckInCount}`,
            })
            .where(
              and(
                eq(eventRegistrations.id, lockedRegistration.id),
                eq(eventRegistrations.tenantId, tenant.id),
                eq(eventRegistrations.status, 'CONFIRMED'),
                eq(eventRegistrations.userId, lockedRegistration.userId),
              ),
            )
            .returning({
              checkedInGuestCount: eventRegistrations.checkedInGuestCount,
              checkInTime: eventRegistrations.checkInTime,
              id: eventRegistrations.id,
            });

          const updatedRegistration = updatedRegistrations[0];
          if (!updatedRegistration?.checkInTime) {
            yield* Effect.logError(
              'Locked registration check-in update did not persist',
            ).pipe(
              Effect.annotateLogs({
                registrationId: lockedRegistration.id,
                tenantId: tenant.id,
              }),
            );
            return yield* Effect.fail(
              new EventRegistrationInternalError({
                message:
                  'The check-in could not be saved. Nothing was changed. Try again.',
              }),
            );
          }

          const updatedOptions = yield* tx
            .update(eventRegistrationOptions)
            .set({
              checkedInSpots: sql`${eventRegistrationOptions.checkedInSpots} + ${checkedInSpotCount}`,
            })
            .where(
              and(
                eq(
                  eventRegistrationOptions.id,
                  lockedRegistration.registrationOptionId,
                ),
                eq(
                  eventRegistrationOptions.eventId,
                  lockedRegistration.eventId,
                ),
              ),
            )
            .returning({
              id: eventRegistrationOptions.id,
            });

          if (updatedOptions.length === 0) {
            yield* Effect.logError(
              'Registration option was missing during check-in',
            ).pipe(
              Effect.annotateLogs({
                eventId: lockedRegistration.eventId,
                registrationId: lockedRegistration.id,
                registrationOptionId: lockedRegistration.registrationOptionId,
                tenantId: tenant.id,
              }),
            );
            return yield* Effect.fail(
              new EventRegistrationInternalError({
                message:
                  'The sign-up choice is unavailable, so no check-in was recorded. Contact an Evorto administrator.',
              }),
            );
          }

          yield* tx.insert(eventRegistrationCheckIns).values({
            actorUserId: user.id,
            attendeeCheckedIn: !lockedRegistration.checkInTime,
            checkInTime: updatedRegistration.checkInTime,
            expectedAttendeeCheckedIn,
            expectedCheckedInGuestCount,
            guestCheckInCount,
            operationKey,
            registrationId: lockedRegistration.id,
            tenantId: tenant.id,
          });

          return {
            _tag: 'CheckedIn' as const,
            alreadyCheckedIn: false,
            checkInTime: updatedRegistration.checkInTime,
          };
        }),
      ),
    );

    if (checkedInRegistration._tag === 'TimingIssue') {
      return yield* Effect.fail(
        checkInUnavailableError(checkedInRegistration.reason),
      );
    }
    // The check-in is committed. A failed ticket read must not turn it into
    // an error: the helper would retry and could not tell what happened.
    const scannedRegistration = yield* loadRegistrationScan({
      registrationId,
      tenantId: tenant.id,
      user,
    }).pipe(
      // An interrupted request stays interrupted; only a failed read is
      // reported as a check-in without fresh ticket details.
      Effect.catchCause((cause) =>
        Cause.hasInterruptsOnly(cause)
          ? Effect.failCause(cause)
          : Effect.logError(
              'Ticket read failed after a committed check-in',
            ).pipe(
              Effect.annotateLogs({
                cause: Cause.pretty(cause),
                registrationId,
                tenantId: tenant.id,
              }),
              Effect.as(null),
            ),
      ),
    );
    return {
      alreadyCheckedIn: checkedInRegistration.alreadyCheckedIn,
      checkInTime: checkedInRegistration.checkInTime.toISOString(),
      registration: scannedRegistration,
    };
  }).pipe(Effect.catch(mapCheckInMutationInternalError)),
