+  @if (scanResultQuery.isPending()) {
+    <p role="status">Loading ticket…</p>
+  } @else if (scanResultQuery.isError()) {
+    <div
+      class="bg-error-container text-on-error-container rounded p-3"
+      role="alert"
+    >
+      <p>{{ queryErrorMessage() }}</p>
+    </div>
+  } @else if (scanResultQuery.isSuccess()) {
+    @let scanResult = scanResultQuery.data();
+    <p class="body-medium">{{ scanResult.registrationOption.title }}</p>
