+      <p class="body-small text-on-surface-variant mt-1">
+        Includes {{ scanResult.guestCount }}
+        {{ scanResult.guestCount === 1 ? "guest" : "guests" }}.
+        {{ scanResult.checkedInGuestCount }} checked in,
+        {{ scanResult.remainingGuestCount }} remaining.
+      </p>
+    }
+    @let timingIssue =
