+      >
+        <p class="title-small">{{ timingIssue.title }}</p>
+        <p>{{ timingIssue.body }}</p>
+      </div>
+    }
+    @let statusIssue =
+      scanRegistrationStatusIssueCopy(scanResult.registrationStatus);
+    @if (statusIssue) {
+      <div
+        class="bg-error-container text-on-error-container mt-3 rounded p-3"
+        role="alert"
+      >
+        <p class="title-small">{{ statusIssue.title }}</p>
+        <p>{{ statusIssue.body }}</p>
+      </div>
+    }
