+        class="bg-error-container text-on-error-container mt-3 rounded p-3"
+        role="alert"
+      >
+        <p class="title-small">
+          This ticket now belongs to {{ scanResult.user.firstName }}
+          {{ scanResult.user.lastName }}
+        </p>
+        <p>
+          It was transferred after the list loaded. Close this dialog and check
+          the updated list.
+        </p>
+      </div>
+    }
+    @if (scanResult.sameUserIssue) {
+      <div
+        class="bg-error-container text-on-error-container mt-3 rounded p-3"
