  );
  protected readonly selectedSpotCheckInCount = computed(() => {
    const ticket = this.ticket();
    if (!ticket) {
      return 0;
    }
    return (
      (ticket.attendeeCheckedIn ? 0 : 1) + this.selectedGuestCheckInCount()
    );
