        },
        onSuccess: (result) => {
          this.dialogRef.disableClose = false;
          this.dialogRef.close({
            alreadyCheckedIn: result.alreadyCheckedIn,
            checkedInGuestCount,
          });
          void this.queryClient.invalidateQueries(
            this.rpc.queryFilter(['events', 'registrationScanned']),
          );
        },
      },
    );
  }
