34 const normalizeInternalServerRpcOrigin = (value: string): string => {
35   if (/^https?:\/\/[^/\\\s@?#]+:\/?$/iu.test(value)) {
36     throw new ServerRpcOriginResolutionError(
37       'SSR_RPC_ORIGIN must not include an empty port',
38     );
39   }
40 
41   let url: URL;
42   try {
43     url = new URL(value);
44   } catch {
45     throw new ServerRpcOriginResolutionError(
46       'SSR_RPC_ORIGIN must be an absolute HTTP or HTTPS URL',
47     );
48   }
49 
50   if (url.protocol !== 'http:' && url.protocol !== 'https:') {
51     throw new ServerRpcOriginResolutionError(
52       'SSR_RPC_ORIGIN must use HTTP or HTTPS',
53     );
54   }
55 
56   if (!isLoopbackHostname(url.hostname)) {
57     throw new ServerRpcOriginResolutionError(
58       'SSR_RPC_ORIGIN must point to a loopback host',
59     );
60   }
61 
62   if (
63     !/^https?:\/\/[^/\\\s@?#]+\/?$/iu.test(value) ||
64     url.username !== '' ||
65     url.password !== '' ||
66     (url.pathname !== '' && url.pathname !== '/') ||
67     url.search !== '' ||
68     url.hash !== ''
69   ) {
70     throw new ServerRpcOriginResolutionError(
71       'SSR_RPC_ORIGIN must be an origin without credentials, a path, a query, or a fragment',
72     );
73   }
74 
75   return url.origin;
76 };
